<?php
declare(strict_types=1);
require __DIR__.'/store-common.php';
$pdo=store_setup();store_customer_required();
$ids=array_values(array_filter(array_map('intval',array_keys($_SESSION['cart']))));$items=[];
if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT id,name,stock FROM products WHERE id IN ($marks)");$s->execute($ids);foreach($s->fetchAll() as $p){$qty=min((int)($_SESSION['cart'][$p['id']]??0),(int)$p['stock']);if($qty>0){$p['quantity']=$qty;$items[]=$p;}}}
if(!$items){notice('سبد خرید خالی است یا محصولات آن موجود نیستند.');go('cart.php');}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$recipient=trim((string)($_POST['recipient_name']??''));$phone=trim((string)($_POST['recipient_phone']??($_SESSION['customer_phone']??'')));$method=(string)($_POST['delivery_method']??'');$address=trim((string)($_POST['address']??''));$when=str_replace('T',' ',(string)($_POST['delivery_at']??''));$dt=DateTime::createFromFormat('Y-m-d H:i',$when);
 try{if($recipient===''||mb_strlen($recipient)>160)throw new RuntimeException('نام تحویل‌گیرنده را وارد کن.');if(!preg_match('/^09[0-9]{9}$/',$phone))throw new RuntimeException('شماره موبایل تحویل‌گیرنده معتبر نیست.');if(!in_array($method,['courier','pickup','digital'],true))throw new RuntimeException('نحوه تحویل را انتخاب کن.');if($address==='')throw new RuntimeException('آدرس یا محل تحویل را وارد کن.');if(!$dt||$dt->format('Y-m-d H:i')!==$when||$dt<new DateTime('+1 hour'))throw new RuntimeException('زمان تحویل باید حداقل یک ساعت بعد از زمان فعلی باشد.');
 $pdo->beginTransaction();$locked=[];$ids=array_column($items,'id');$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT id,name,stock FROM products WHERE id IN ($marks) FOR UPDATE");$s->execute($ids);foreach($s->fetchAll() as $p)$locked[(int)$p['id']]=$p;
 foreach($items as $it){if(!isset($locked[$it['id']])||(int)$locked[$it['id']]['stock']<(int)$it['quantity'])throw new RuntimeException('موجودی یکی از محصولات تغییر کرده؛ سبد را بررسی کن.');}
 $s=$pdo->prepare("INSERT INTO orders(user_id,total,delivery_method,delivery_at,address,recipient_name,recipient_phone,status) VALUES(?,0,?,?,?,?,?,'new')");$s->execute([(int)$_SESSION['customer_id'],$method,$dt->format('Y-m-d H:i:s'),$address,$recipient,$phone]);$orderId=(int)$pdo->lastInsertId();
 $oi=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,quantity,unit_price) VALUES(?,?,?,?,0)');$up=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=? AND stock>=?');
 foreach($items as $it){$oi->execute([$orderId,$it['id'],$locked[$it['id']]['name'],$it['quantity']]);$up->execute([$it['quantity'],$it['id'],$it['quantity']]);if($up->rowCount()!==1)throw new RuntimeException('موجودی محصول کافی نیست.');}
 $pdo->commit();$_SESSION['cart']=[];notice('سفارش رایگان شما با موفقیت ثبت شد. کد سفارش: '.$orderId);go('orders.php');
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'ثبت سفارش انجام نشد؛ دوباره تلاش کن.';}
}
store_header($pdo,'تکمیل سفارش');if($error)echo '<div class="shop-alert error">'.e($error).'</div>';
$minDate=date('Y-m-d\TH:i',time()+3600);
echo '<section class="shop-panel"><h1>تکمیل سفارش</h1><p class="shop-muted">روش پرداختی وجود ندارد؛ جمع کل این سفارش ۰ تومان است.</p><div style="margin-bottom:22px">';foreach($items as $it)echo '<p>'.e($it['name']).' × '.(int)$it['quantity'].' <span class="shop-price">— رایگان</span></p>';echo '<h3>جمع کل: ۰ تومان</h3></div><form method="post" class="shop-form"><input type="hidden" name="_csrf" value="'.e(csrf()).'"><label>نام تحویل‌گیرنده<input name="recipient_name" maxlength="160" required value="'.e((string)($_POST['recipient_name']??'')).'"></label><label>شماره موبایل تحویل‌گیرنده<input name="recipient_phone" inputmode="numeric" pattern="09[0-9]{9}" maxlength="11" required value="'.e((string)($_POST['recipient_phone']??($_SESSION['customer_phone']??''))).'"></label><label>نحوه تحویل<select name="delivery_method" required><option value="">انتخاب کن</option><option value="courier">ارسال به آدرس</option><option value="pickup">تحویل حضوری</option><option value="digital">تحویل دیجیتال / آنلاین</option></select></label><label>آدرس کامل یا محل تحویل<textarea name="address" placeholder="شهر، خیابان، پلاک، واحد یا توضیحات محل تحویل">'.e((string)($_POST['address']??'')).'</textarea></label><label>زمان پیشنهادی تحویل<input type="datetime-local" name="delivery_at" min="'.e($minDate).'" required value="'.e((string)($_POST['delivery_at']??'')).'"></label><button class="shop-btn">ثبت سفارش رایگان</button></form></section>';
store_footer();
